#!/usr/bin/env python3
"""Atomic no-gallery Mirza bridge migration.

For the confirmed old live layout with no private storage (3 Unpaid receipts).
Only insert private helper handlers and replace known receipt handler.
This migrates NO order state and NEVER charges, approves or rejects a payment.
Full exact-match checks and PHP lint before atomic swap with root-only backup.
"""
import os, shutil, subprocess, sys, tempfile
from datetime import datetime, timezone
from pathlib import Path

OLD_RECEIPT="function vpnappSubmitReceipt(PDO $db, $u, $key, $encoded) {\n    if (!is_string($encoded) || strlen($encoded)>2800000 ||\n        !preg_match('/^[A-Za-z0-9+\\/=]+$/D',$encoded))\n        vpnappError(400,'Invalid image data');\n    $data=base64_decode($encoded,true);\n    if ($data===false || strlen($data)<200 || strlen($data)>2000000)\n        vpnappError(400,'Invalid image size');\n    $kind=(new finfo(FILEINFO_MIME_TYPE))->buffer($data);\n    $image=@getimagesizefromstring($data);\n    if (!in_array($kind,['image/png','image/jpeg'],true) || !$image ||\n        $image[0]>5000 || $image[1]>5000)\n        vpnappError(400,'Unsupported image');\n    // Duplicate image upload is allowed only to retry a failed Telegram\n    // notification for the same order. It never changes payment state again.\n    $db->beginTransaction();\n    $stmt=$db->prepare(\"SELECT payment_id,status,result_json FROM vpnapp_orders\n        WHERE owner_id=? AND external_id=? FOR UPDATE\");\n    $stmt->execute([$u['id'],$key]);$order=$stmt->fetch(PDO::FETCH_ASSOC);\n    if (!$order) {$db->rollBack();vpnappError(404,'Order not found');}\n    $stored=json_decode($order['result_json']??'null',true);\n    if (!is_array($stored)) $stored=[];\n    // A past group success is not proof that the bot owner saw the photo.\n    // Explicit re-upload of this same order may retry private delivery, but\n    // it must never create a second payment or repeat too rapidly.\n    $lastAttempt=(int)($stored['receipt_last_attempt_at']??0);\n    $sendAttempts=(int)($stored['receipt_send_attempts']??0);\n    if ($lastAttempt>time()-30) {\n        $db->rollBack();\n        vpnappError(429,'Wait 30 seconds before retrying this receipt');\n    }\n    if ($sendAttempts>=8) {\n        $db->rollBack();\n        vpnappError(429,'Receipt delivery retry limit reached; contact support');\n    }\n    if (!in_array($order['status'],['awaiting_receipt','waiting'],true)) {\n        $db->rollBack();vpnappError(409,'Order is not awaiting receipt');\n    }\n    if ($order['status']==='awaiting_receipt') {\n        $update=$db->prepare(\"UPDATE Payment_report\n            SET payment_Status='waiting',at_updated=?,dec_not_confirmed='VPN app receipt'\n            WHERE id_order=? AND id_user=? AND payment_Status='Unpaid'\");\n        $update->execute([date('Y/m/d H:i:s'),$order['payment_id'],$u['id']]);\n        if ($update->rowCount()!=1) {\n            $db->rollBack();vpnappError(409,'Payment is not pending');\n        }\n        $db->prepare(\"UPDATE vpnapp_orders SET status='waiting',updated_at=?\n            WHERE external_id=? AND owner_id=?\")->execute([time(),$key,$u['id']]);\n    }\n    // Reserve a retry attempt before leaving the locked transaction;\n    // parallel mobile requests cannot flood Telegram with the same receipt.\n    $stored['receipt_last_attempt_at']=time();\n    $stored['receipt_send_attempts']=$sendAttempts+1;\n    // A previous group notification is not proof of a private admin photo;\n    // reset the confirmation before each intentional retry.\n    $stored['receipt_notice_sent']=false;\n    $db->prepare(\"UPDATE vpnapp_orders SET result_json=?,updated_at=?\n        WHERE external_id=? AND owner_id=?\")->execute([\n        json_encode($stored,JSON_UNESCAPED_UNICODE),time(),$key,$u['id']]);\n    $db->commit();\n\n    $sent=false;\n    $tmp=tempnam(sys_get_temp_dir(),'vpnreceipt_');\n    if ($tmp!==false) {\n        try {\n            if (file_put_contents($tmp,$data,LOCK_EX)!==false) {\n                @chmod($tmp,0600);\n                $sent=vpnappNotify('🧾 رسید کارت‌به‌کارت از اپ VPN'. \"\\n\".\n                    'کاربر: '.htmlspecialchars($u['id'],ENT_QUOTES,'UTF-8'). \"\\n\".\n                    'پیگیری: '.htmlspecialchars($order['payment_id'],ENT_QUOTES,'UTF-8'). \"\\n\".\n                    'وضعیت: منتظر پردازش میرزا', $u['id'],$tmp,$order['payment_id']);\n            }\n        } finally { @unlink($tmp); }\n    }\n    if ($sent) {\n        $db->beginTransaction();\n        $query=$db->prepare(\"SELECT result_json FROM vpnapp_orders\n            WHERE owner_id=? AND external_id=? FOR UPDATE\");\n        $query->execute([$u['id'],$key]);\n        $latest=json_decode((string)$query->fetchColumn(),true);\n        if (!is_array($latest)) $latest=[];\n        $latest['receipt_notice_sent']=true;\n        $db->prepare(\"UPDATE vpnapp_orders SET result_json=?,updated_at=?\n            WHERE owner_id=? AND external_id=?\")->execute([\n            json_encode($latest,JSON_UNESCAPED_UNICODE),time(),$u['id'],$key]);\n        $db->commit();\n    } else {\n        error_log('[vpnapp] Receipt saved but Telegram report delivery unconfirmed');\n    }\n    return ['status'=>'waiting','notification_delivered'=>$sent];\n}\n"
NEW_RECEIPT="function vpnappSubmitReceipt(PDO $db, $u, $key, $encoded) {\n    if (!is_string($encoded) || strlen($encoded)>2800000 ||\n        !preg_match('/^[A-Za-z0-9+\\/=]+$/D',$encoded))\n        vpnappError(400,'Invalid image data');\n    $data=base64_decode($encoded,true);\n    if ($data===false || strlen($data)<200 || strlen($data)>2000000)\n        vpnappError(400,'Invalid image size');\n    $kind=(new finfo(FILEINFO_MIME_TYPE))->buffer($data);\n    $image=@getimagesizefromstring($data);\n    if (!in_array($kind,['image/png','image/jpeg'],true) || !$image ||\n        $image[0]>5000 || $image[1]>5000)\n        vpnappError(400,'Unsupported image');\n    // Keep an optional encrypted-volume/private-directory copy for the\n    // authenticated Iran admin image viewer. Never expose this file by URL.\n    // Duplicate image upload is allowed only to retry a failed Telegram\n    // notification for the same order. It never changes payment state again.\n    $db->beginTransaction();\n    $stmt=$db->prepare(\"SELECT payment_id,status,result_json FROM vpnapp_orders\n        WHERE owner_id=? AND external_id=? FOR UPDATE\");\n    $stmt->execute([$u['id'],$key]);$order=$stmt->fetch(PDO::FETCH_ASSOC);\n    if (!$order) {$db->rollBack();vpnappError(404,'Order not found');}\n    $stored=json_decode($order['result_json']??'null',true);\n    if (!is_array($stored)) $stored=[];\n    // A past group success is not proof that the bot owner saw the photo.\n    // Explicit re-upload of this same order may retry private delivery, but\n    // it must never create a second payment or repeat too rapidly.\n    $lastAttempt=(int)($stored['receipt_last_attempt_at']??0);\n    $sendAttempts=(int)($stored['receipt_send_attempts']??0);\n    if ($order['status']==='waiting' && !empty($stored['receipt_notice_sent'])) {\n        $db->commit();\n        return ['status'=>'waiting','notification_delivered'=>true,\n                'notification_queued'=>false,\n                'receipt_stored'=>vpnappPrivateReceiptExists($key)];\n    }\n    if ($lastAttempt>time()-30) {\n        $db->rollBack();\n        vpnappError(429,'Wait 30 seconds before retrying this receipt');\n    }\n    if ($sendAttempts>=8) {\n        $db->rollBack();\n        vpnappError(429,'Receipt delivery retry limit reached; contact support');\n    }\n    if (!in_array($order['status'],['awaiting_receipt','waiting'],true)) {\n        $db->rollBack();vpnappError(409,'Order is not awaiting receipt');\n    }\n    // Only after verifying the authenticated owner and an eligible order\n    // can the receipt be written to a private, non-public directory.\n    $privateStored=vpnappPersistReceipt($key,$data,$kind);\n    if (!$privateStored) {\n        $db->rollBack();\n        vpnappError(503,'Private receipt storage is unavailable; retry later');\n    }\n    if ($order['status']==='awaiting_receipt') {\n        $update=$db->prepare(\"UPDATE Payment_report\n            SET payment_Status='waiting',at_updated=?,dec_not_confirmed='VPN app receipt'\n            WHERE id_order=? AND id_user=? AND payment_Status='Unpaid'\");\n        $update->execute([date('Y/m/d H:i:s'),$order['payment_id'],$u['id']]);\n        if ($update->rowCount()!=1) {\n            $db->rollBack();vpnappError(409,'Payment is not pending');\n        }\n        $db->prepare(\"UPDATE vpnapp_orders SET status='waiting',updated_at=?\n            WHERE external_id=? AND owner_id=?\")->execute([time(),$key,$u['id']]);\n    }\n    // Saving the image and marking payment 'waiting' is the checkout\n    // transaction. Telegram is delivered by a separate CLI worker using\n    // the private receipt file; never hold the mobile HTTP request for\n    // multiple 16s sendPhoto calls (which caused Iran Nginx HTTP 504).\n    // Keep attempts from earlier retries. Re-upload never circumvents the\n    // bounded retry limit or creates duplicate notifications after delivery.\n    $stored['receipt_last_attempt_at']=$lastAttempt;\n    $stored['receipt_send_attempts']=$sendAttempts;\n    $stored['receipt_notice_sent']=false;\n    $db->prepare(\"UPDATE vpnapp_orders SET result_json=?,updated_at=?\n        WHERE external_id=? AND owner_id=?\")->execute([\n        json_encode($stored,JSON_UNESCAPED_UNICODE),time(),$key,$u['id']]);\n    $db->commit();\n    return ['status'=>'waiting','notification_delivered'=>false,\n            'notification_queued'=>true,'receipt_stored'=>true];\n}\n"
STORAGE_HELPERS="function vpnappPrivateReceiptDir() {\n    return dirname(__DIR__,2).'/mirza-vpnapp-receipts';\n}\nfunction vpnappReceiptFile($key, $mime) {\n    if (!preg_match('/^[0-9a-f-]{36}$/D',(string)$key)) return null;\n    $ext=$mime==='image/png'?'.png':'.jpg';\n    // Same path from PHP-FPM and CLI worker; their environment variables\n    // may differ. The random 128-bit order identifier + a 0700 private dir\n    // prevent directory enumeration or public receipt exposure.\n    return vpnappPrivateReceiptDir().'/'.hash('sha256',(string)$key).$ext;\n}\n/**\n * Locate an image saved by either the previous HMAC-based receipt code or the\n * newer stable naming scheme. This is only used within a private 0700 folder.\n * Never expose a filesystem path to the API caller.\n */\nfunction vpnappFindReceipt($key, $mime) {\n    $preferred=vpnappReceiptFile($key,$mime);\n    if ($preferred && is_file($preferred) && !is_link($preferred)) return $preferred;\n    if (!preg_match('/^[0-9a-f-]{36}$/D',(string)$key)) return null;\n    $ext=$mime==='image/png'?'.png':'.jpg';\n    $secrets=[trim((string)getenv('MIRZA_APP_BRIDGE_SECRET')),''];\n    foreach (array_unique($secrets) as $secret) {\n        $path=vpnappPrivateReceiptDir().'/'.\n            hash_hmac('sha256',(string)$key,$secret).$ext;\n        if (is_file($path) && !is_link($path)) return $path;\n    }\n    return null;\n}\nfunction vpnappPersistReceipt($key, $data, $mime) {\n    $directory=vpnappPrivateReceiptDir();\n    if (!is_dir($directory) || !is_writable($directory) || is_link($directory)) {\n        error_log('[vpnapp] Private receipt storage not configured; Telegram delivery still attempted');\n        return false;\n    }\n    $path=vpnappReceiptFile($key,$mime);\n    if (!$path) return false;\n    $temporary=tempnam($directory,'.upload-');\n    if ($temporary===false) return false;\n    try {\n        @chmod($temporary,0600);\n        if (file_put_contents($temporary,$data,LOCK_EX)!==strlen($data)) return false;\n        if (!rename($temporary,$path)) return false;\n        return true;\n    } finally {\n        if (is_file($temporary)) @unlink($temporary);\n    }\n}\nfunction vpnappPrivateReceiptExists($key) {\n    return vpnappFindReceipt($key,'image/jpeg') !== null ||\n        vpnappFindReceipt($key,'image/png') !== null;\n}\nfunction vpnappAdminReceipt(PDO $db, $key) {\n    if (!preg_match('/^[0-9a-f-]{36}$/D',(string)$key))\n        vpnappError(400,'Invalid order ID');\n    $stmt=$db->prepare(\"SELECT external_id FROM vpnapp_orders WHERE external_id=?\n        AND kind IN ('card','renewal_card') LIMIT 1\");\n    $stmt->execute([$key]);\n    if (!$stmt->fetchColumn()) vpnappError(404,'Order not found');\n    foreach (['image/jpeg','image/png'] as $mime) {\n        $path=vpnappFindReceipt($key,$mime);\n        if (!$path) continue;\n        $size=filesize($path);\n        if ($size===false || $size<200 || $size>1500000) continue;\n        $bytes=file_get_contents($path);\n        if (!is_string($bytes) || strlen($bytes)!==$size) continue;\n        return ['ok'=>true,'image_base64'=>base64_encode($bytes),\n                'content_type'=>$mime];\n    }\n    vpnappError(404,'Receipt image not stored; customer may resubmit it');\n}\n\n"
OLD_GATE="    if ($action==='admin_snapshot' &&\n        (string)($input['telegram_id']??'')==='0') {\n        vpnappReply(200,vpnappAdminSnapshot($pdo));\n    }\n"
NEW_GATE="    if ((string)($input['telegram_id']??'')==='0') {\n        if ($action==='admin_snapshot')\n            vpnappReply(200,vpnappAdminSnapshot($pdo));\n        if ($action==='admin_receipt')\n            vpnappReply(200,vpnappAdminReceipt($pdo,(string)($input['order_id']??'')));\n    }\n"
OLD_INFO_STATUS="    if (in_array($result['kind'],['card','renewal_card'],true)) {\n        $result['notification_delivered']=!empty($stored['receipt_notice_sent']);\n    }"
NEW_INFO_STATUS="    if (in_array($result['kind'],['card','renewal_card'],true)) {\n        $result['notification_delivered']=!empty($stored['receipt_notice_sent']);\n        $result['receipt_stored']=vpnappPrivateReceiptExists($order);\n        $result['notification_queued']=$result['receipt_stored'] &&\n            !$result['notification_delivered'];\n    }"
OLD_INFO_JOIN="FROM vpnapp_orders o LEFT JOIN Payment_report p ON p.id_order=o.payment_id\n        LEFT JOIN invoice i ON i.id_invoice=o.invoice_id AND i.id_user=o.owner_id"
NEW_INFO_JOIN="FROM vpnapp_orders o LEFT JOIN Payment_report p\n            ON p.id_order COLLATE utf8mb4_unicode_ci =\n               o.payment_id COLLATE utf8mb4_unicode_ci\n        LEFT JOIN invoice i ON i.id_invoice COLLATE utf8mb4_unicode_ci =\n               o.invoice_id COLLATE utf8mb4_unicode_ci AND i.id_user=o.owner_id"
SNAP_OLD="        unset($entry['result_json']); // Never expose private order payloads."
SNAP_NEW="        $entry['has_receipt']=vpnappPrivateReceiptExists($entry['id']);\n        unset($entry['result_json']); // Never expose private order payloads."

def swap_once(s,old,new,label):
    if s.count(new)==1 and s.count(old)==0:
        return s
    if s.count(old)!=1 or s.count(new):
        raise RuntimeError(label+": live code differs; no changes")
    return s.replace(old,new,1)

def build(original: bytes):
    s=original.decode('utf-8')
    if "function vpnappPrivateReceiptDir(" in s:
        raise RuntimeError("Gallery already present; legacy migration is not applicable")
    # Check all old handler variants before creating any file.
    if s.count(OLD_RECEIPT)!=1:
        raise RuntimeError("Receipt upload differs from known legacy handler; no changes")
    if s.count(OLD_GATE)!=1:
        raise RuntimeError("Authenticated admin route differs; no changes")
    if s.count(OLD_INFO_STATUS)!=1:
        raise RuntimeError("Receipt status helper differs; no changes")
    if s.count(SNAP_OLD)!=1 or "has_receipt" in s:
        raise RuntimeError("Admin snapshot differs; no changes")
    if s.count(OLD_INFO_JOIN)==1:
        s=s.replace(OLD_INFO_JOIN,NEW_INFO_JOIN,1)
    elif s.count(NEW_INFO_JOIN)!=1:
        raise RuntimeError("ReceiptInfo JOIN differs; no changes")
    s=s.replace(OLD_INFO_STATUS,NEW_INFO_STATUS,1)
    s=s.replace(SNAP_OLD,SNAP_NEW,1)
    s=s.replace(OLD_GATE,NEW_GATE,1)
    s=s.replace(OLD_RECEIPT,STORAGE_HELPERS+NEW_RECEIPT,1)
    return s.encode('utf-8')

def patch(live: Path, backups: Path):
    if not live.is_file() or live.is_symlink():
        raise RuntimeError("Live Mirza PHP file invalid")
    original=live.read_bytes()
    after=build(original)
    backups.mkdir(parents=True,mode=0o700,exist_ok=True)
    backup=backups/("vpnapp.php.before-gallery-migration-"+
                    datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S-%f"))
    shutil.copy2(live,backup)
    fd,temp=tempfile.mkstemp(prefix=".mirza-gallery-",suffix=".php",dir=live.parent)
    try:
        with os.fdopen(fd,'wb') as w: w.write(after)
        st=live.stat()
        shutil.copymode(live,temp)
        if os.geteuid()==0:
            os.chown(temp,st.st_uid,st.st_gid)
        proc=subprocess.run(["php","-l",temp],capture_output=True,text=True)
        if proc.returncode:
            raise RuntimeError("PHP syntax check failed: "+proc.stdout+proc.stderr)
        os.replace(temp,live)
        print("BACKUP:",backup)
        print("LEGACY_PRIVATE_RECEIPT_QUEUE_INSTALLED")
    finally:
        if os.path.exists(temp): os.unlink(temp)

if __name__=="__main__":
    if len(sys.argv)!=2:
        raise SystemExit("Usage: sudo python3 patch_vpnapp_no_gallery.py /absolute/api/vpnapp.php")
    try:
        patch(Path(sys.argv[1]),Path('/root/mirza-backups'))
    except (RuntimeError,OSError,UnicodeError) as err:
        print("ABORTED; LIVE PHP UNCHANGED:",err,file=sys.stderr)
        sys.exit(1)
